'use client';

import { useTranslations } from 'next-intl';
import { education } from '@/data/career';
import { GraduationCap, Calendar, MapPin } from 'iconoir-react';

interface EducationProps {
  locale: string;
}

export default function Education({ locale }: EducationProps) {
  const t = useTranslations('education');

  return (
    <section id="education" className="py-20 bg-white dark:bg-gray-900">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900 dark:text-white mb-4">
            {t('title')}
          </h2>
          <p className="text-xl text-gray-600 dark:text-gray-400">
            {t('subtitle')}
          </p>
        </div>

        <div className="max-w-4xl mx-auto space-y-8">
          {education.map((edu) => (
            <div
              key={edu.id}
              className="bg-gray-50 dark:bg-gray-800 rounded-xl p-6 md:p-8 shadow-lg"
            >
              <div className="flex items-start gap-4">
                <div className="flex-shrink-0">
                  <GraduationCap className="w-12 h-12 text-purple-600 dark:text-purple-400" />
                </div>
                <div className="flex-1">
                  <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
                    {edu.degree} - {edu.field}
                  </h3>
                  <h4 className="text-xl text-purple-600 dark:text-purple-400 mb-4">
                    {edu.institution}
                  </h4>
                  <div className="flex flex-wrap items-center gap-4 text-gray-600 dark:text-gray-400">
                    <div className="flex items-center gap-1">
                      <Calendar className="w-4 h-4" />
                      <span>
                        {edu.startDate} - {edu.endDate}
                      </span>
                    </div>
                    <div className="flex items-center gap-1">
                      <MapPin className="w-4 h-4" />
                      <span>{edu.location}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

