'use client';

import { useTranslations } from 'next-intl';
import { personalInfo } from '@/data/career';
import { ArrowDown, Mail, MapPin } from 'iconoir-react';
import { Link } from '@/i18n/routing';

interface HeroProps {
  locale: string;
}

export default function Hero({ locale }: HeroProps) {
  const t = useTranslations('hero');

  return (
    <section className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 via-white to-purple-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 pt-16">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
        <div className="text-center">
          <div className="mb-8">
            <div className="inline-block w-32 h-32 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 mb-6 flex items-center justify-center text-4xl font-bold text-white">
              {personalInfo.name.split(' ').map(n => n[0]).join('')}
            </div>
          </div>
          
          <h1 className="text-5xl md:text-7xl font-bold text-gray-900 dark:text-white mb-4">
            {personalInfo.name}
          </h1>
          
          <h2 className="text-2xl md:text-3xl text-gray-600 dark:text-gray-300 mb-6">
            {t('title')}
          </h2>
          
          <p className="text-lg md:text-xl text-gray-500 dark:text-gray-400 max-w-2xl mx-auto mb-8">
            {t('subtitle')}
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 mb-12">
            <div className="flex items-center text-gray-600 dark:text-gray-400">
              <MapPin className="w-5 h-5 mr-2" />
              <span>{personalInfo.location}</span>
            </div>
            {personalInfo.email && (
              <div className="flex items-center text-gray-600 dark:text-gray-400">
                <Mail className="w-5 h-5 mr-2" />
                <a href={`mailto:${personalInfo.email}`} className="hover:text-gray-900 dark:hover:text-white">
                  {personalInfo.email}
                </a>
              </div>
            )}
          </div>

          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link
              href={`/${locale}#projects`}
              className="px-8 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg font-semibold hover:from-blue-700 hover:to-purple-700 transition-all transform hover:scale-105 shadow-lg"
            >
              {t('cta')}
            </Link>
            <Link
              href={`/${locale}#contact`}
              className="px-8 py-3 bg-white dark:bg-gray-800 text-gray-900 dark:text-white border-2 border-gray-300 dark:border-gray-700 rounded-lg font-semibold hover:bg-gray-50 dark:hover:bg-gray-700 transition-all"
            >
              {t('scrollDown')}
            </Link>
          </div>

          <div className="mt-16 animate-bounce">
            <a href="#about" className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
              <ArrowDown className="w-6 h-6 mx-auto" />
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}

